-- PostgreSQL-only constraints deliberately appended to Prisma's baseline SQL.
CREATE EXTENSION IF NOT EXISTS btree_gist;
ALTER TABLE "VehicleOwnership" ADD CONSTRAINT "vehicle_ownership_valid_interval" CHECK ("validUntil" IS NULL OR "validUntil" > "validFrom");
ALTER TABLE "VehicleOwnership" ADD CONSTRAINT "vehicle_ownership_non_overlapping" EXCLUDE USING gist ("vehicleProjectionId" WITH =, tsrange("validFrom", "validUntil", '[)') WITH &&);
CREATE UNIQUE INDEX "one_active_transfer_per_vehicle" ON "Application" ("vehicleProjectionId") WHERE "state" NOT IN ('REJECTED', 'REGISTRY_UPDATE_COMPLETE', 'WITHDRAWN_EXTERNALLY_CONFIRMED');
CREATE UNIQUE INDEX "one_confirmed_attempt_per_payment" ON "PaymentAttempt" ("paymentId") WHERE "status" = 'CONFIRMED';
CREATE UNIQUE INDEX "one_unresolved_attempt_per_payment" ON "PaymentAttempt" ("paymentId") WHERE "status" IN ('REQUESTED', 'PENDING', 'RECONCILIATION_REQUIRED');
CREATE UNIQUE INDEX "one_open_reconciliation_per_payment" ON "PaymentReconciliation" ("paymentId") WHERE "status" = 'OPEN';
CREATE INDEX "OperatorAction_operatorId_action_createdAt_idx" ON "OperatorAction"("operatorId", "action", "createdAt");
